    'approved_total', COALESCE(SUM(COALESCE(gross_amount, amount)) FILTER (WHERE status IN ('approved','paid')), 0),
    'rejected_count', COUNT(*) FILTER (WHERE status = 'rejected'),
    'pending_count',  COUNT(*) FILTER (WHERE status = 'pending')
